import { useId, useState } from "react";
import Box from "@mui/material/Box";
import Collapse from "@mui/material/Collapse";
import FormControl from "@mui/material/FormControl";
import IconButton from "@mui/material/IconButton";
import InputLabel from "@mui/material/InputLabel";
import MenuItem from "@mui/material/MenuItem";
import Select from "@mui/material/Select";
import Stack from "@mui/material/Stack";
import ToggleButton from "@mui/material/ToggleButton";
import ToggleButtonGroup from "@mui/material/ToggleButtonGroup";
import FilterListIcon from "@mui/icons-material/FilterList";
import { Filter as FilterType, PriorityFilter } from "../types/todo.types";

interface FilterBarProps {
  activeFilter: FilterType;
  activePriorityFilter: PriorityFilter;
  onFilterChange: (filter: FilterType) => void;
  onPriorityFilterChange: (filter: PriorityFilter) => void;
}

export function FilterBar({
  activeFilter,
  activePriorityFilter,
  onFilterChange,
  onPriorityFilterChange,
}: FilterBarProps) {
  const filters: FilterType[] = ["all", "active", "completed"];
  const filtersId = useId();
  const priorityFilterLabelId = useId();
  const filterNames: Record<FilterType, string> = {
    all: "Wszystkie",
    active: "Aktywne",
    completed: "Ukończone",
  };

  const [showFilters, setShowFilters] = useState(true);

  return (
    <Stack
      component="section"
      aria-label="Filtr zadań"
      spacing={1.5}
      alignItems="center"
      sx={{ mx: "auto", my: 2.5, width: "100%", maxWidth: 700 }}
    >
      <Box sx={{ width: "100%", display: "flex", justifyContent: "flex-end" }}>
        <IconButton
          type="button"
          aria-label="Pokaż lub ukryj filtry zadań"
          aria-controls={filtersId}
          aria-expanded={showFilters}
          onClick={() => setShowFilters((prev) => !prev)}
          color="primary"
        >
          <FilterListIcon />
        </IconButton>
      </Box>

      <Collapse in={showFilters} unmountOnExit>
        <Stack
          id={filtersId}
          direction={{ xs: "column", sm: "row" }}
          spacing={1.5}
          alignItems={{ xs: "stretch", sm: "center" }}
          justifyContent="center"
        >
          <ToggleButtonGroup
            exclusive
            value={activeFilter}
            aria-label="Filtr statusu zadań"
            onChange={(_, value: FilterType | null) => {
              if (value) {
                onFilterChange(value);
              }
            }}
            sx={{ flexWrap: "wrap", justifyContent: "center", gap: 1 }}
          >
            {filters.map((filter) => (
              <ToggleButton
                key={filter}
                value={filter}
                aria-label={`Pokaż ${filterNames[filter].toLowerCase()} zadania`}
                sx={{ minHeight: 44, px: 2, border: 1, borderColor: "divider" }}
              >
                {filterNames[filter]}
              </ToggleButton>
            ))}
          </ToggleButtonGroup>

          <FormControl size="small" sx={{ minWidth: { xs: "100%", sm: 180 } }}>
            <InputLabel id={priorityFilterLabelId}>Priorytet</InputLabel>
            <Select
              labelId={priorityFilterLabelId}
              value={activePriorityFilter}
              label="Priorytet"
              onChange={(event) => {
                onPriorityFilterChange(event.target.value as PriorityFilter);
              }}
            >
              <MenuItem value="all">Wszystkie</MenuItem>
              <MenuItem value="low">Niski</MenuItem>
              <MenuItem value="medium">Średni</MenuItem>
              <MenuItem value="high">Wysoki</MenuItem>
            </Select>
          </FormControl>
        </Stack>
      </Collapse>
    </Stack>
  );
}
